package com.geekmall.trade;
import com.geekmall.common.api.ApiResponse;import jakarta.servlet.http.HttpServletRequest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/v1/admin/trade") @PreAuthorize("hasRole('SYSTEM_ADMIN')") class TradeAdminController{private final JdbcTemplate jdbc;private final TradeRecoveryJobs jobs;TradeAdminController(JdbcTemplate jdbc,TradeRecoveryJobs jobs){this.jdbc=jdbc;this.jobs=jobs;}@PostMapping("/outbox/retry")ApiResponse<Map<String,Integer>> retry(HttpServletRequest r){int n=jdbc.update("UPDATE event_outbox SET status='PENDING',next_retry_at=CURRENT_TIMESTAMP WHERE status='FAILED'");return ApiResponse.success(Map.of("retried",n),String.valueOf(r.getAttribute("requestId")));}@PostMapping("/reconcile")ApiResponse<Map<String,String>> reconcile(HttpServletRequest r){jobs.closeExpired();jobs.compensate();return ApiResponse.success(Map.of("status","COMPLETED"),String.valueOf(r.getAttribute("requestId")));}}
